$$

$$
= \boldsymbol {\Sigma} _ {p} - \mathbf {K} \boldsymbol {\Sigma} _ {o} \left(\boldsymbol {\Sigma} _ {o} ^ {- 1}\right) ^ {\top} \boldsymbol {\Sigma} _ {p o} ^ {\top}
$$

$$
= \boldsymbol {\Sigma} _ {p} - \mathbf {K} \boldsymbol {\Sigma} _ {p o} ^ {\top}
$$

$$
= \boldsymbol {\Sigma} _ {p} - \mathbf {K} \left(\Sigma_ {p} \mathbf {O} _ {s} ^ {\top}\right) ^ {\top}
$$

$$
= \Sigma_ {p} - \mathrm {K O} _ {s} \Sigma_ {p} ^ {\top}
$$

$$
= \Sigma_ {p} - \mathbf {K O} _ {s} \Sigma_ {p}
$$

